const products={tilia:{name:'Tilia Table',base:890,min:120,max:240,standard:180,depth:85,height:75,lead:'6–8 weeks',use:size=>`Seats ${size<150?4:size<210?6:8} comfortably`},arko:{name:'Arko Shelf',base:640,min:80,max:180,standard:120,depth:36,height:190,lead:'5–7 weeks',use:()=>`Four open shelves · wall fixing`},sola:{name:'Sola Bench',base:420,min:90,max:200,standard:140,depth:36,height:45,lead:'4–6 weeks',use:size=>`Seats ${size<150?2:3} comfortably`}};
const woodNames={oak:'Oak',walnut:'Walnut',ash:'Ash'},finishNames={natural:'Natural oil',smoked:'Smoked',matte:'Matte lacquer'};
const woodFees={oak:0,walnut:180,ash:45},finishFees={natural:0,smoked:65,matte:85};
const form=document.querySelector('#config-form'),width=document.querySelector('#width');
function render(){const data=new FormData(form),piece=data.get('piece'),wood=data.get('wood'),finish=data.get('finish'),product=products[piece],size=Number(width.value);const extra=Math.round((size-product.standard)*3.1/10)*10;const total=Math.max(0,product.base+extra+woodFees[wood]+finishFees[finish]);document.querySelector('#width-output').value=`${size} cm`;document.querySelector('#estimate-name').textContent=product.name;document.querySelector('#estimate-spec').textContent=`${woodNames[wood]} · ${size} cm · ${finishNames[finish]}`;document.querySelector('#estimate-dimensions').textContent=`${size} × ${product.depth} × ${product.height} cm`;document.querySelector('#estimate-use').textContent=product.use(size);document.querySelector('#estimate-lead').textContent=product.lead;document.querySelector('#estimate-total').textContent=`€${total.toLocaleString('en-US')}`;document.querySelector('#copy-status').textContent='';const sketch=document.querySelector('#estimate-object');sketch.className=`estimate-object ${piece}`;sketch.style.setProperty('--wood-color',wood==='walnut'?'#6d452b':wood==='ash'?'#d8b984':'#a8784d')}
form.addEventListener('change',event=>{if(event.target.name==='piece'){const p=products[event.target.value];width.min=p.min;width.max=p.max;width.value=p.standard;document.querySelector('#width-min').textContent=`${p.min} cm`;document.querySelector('#width-max').textContent=`${p.max} cm`}render()});width.addEventListener('input',render);
document.querySelectorAll('.product-select').forEach(button=>button.addEventListener('click',()=>{const radio=form.querySelector(`input[name="piece"][value="${button.dataset.product}"]`);radio.checked=true;radio.dispatchEvent(new Event('change',{bubbles:true}));document.querySelector('#configure').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});radio.focus({preventScroll:true})}));render();
document.querySelector('#copy-spec').addEventListener('click',async()=>{const data=new FormData(form),product=products[data.get('piece')],size=Number(width.value),brief=`Honest Grain — design brief (independent demo)\nPiece: ${product.name}\nOverall size: ${size} × ${product.depth} × ${product.height} cm\nTimber: ${woodNames[data.get('wood')]}\nFinish: ${finishNames[data.get('finish')]}\nSuggested use: ${product.use(size)}\nExample lead time: ${product.lead}\nIndicative estimate: ${document.querySelector('#estimate-total').textContent}\nThis is a preview, not a purchase or final quote.`;const status=document.querySelector('#copy-status');try{await navigator.clipboard.writeText(brief);status.textContent='Design brief copied to clipboard.'}catch{status.textContent='Copy is unavailable here. You can still use the specifications shown above.'}});

const mobileMenuButton=document.querySelector('.mobile-menu-toggle');
const mobileHeaderNav=document.querySelector('#mobile-header-nav');
function setMobileHeaderOpen(open){
  mobileMenuButton.setAttribute('aria-expanded',String(open));
  mobileMenuButton.setAttribute('aria-label',open?'Close navigation':'Open navigation');
  mobileHeaderNav.classList.toggle('is-open',open);
}
mobileMenuButton.addEventListener('click',()=>setMobileHeaderOpen(mobileMenuButton.getAttribute('aria-expanded')!=='true'));
mobileHeaderNav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>setMobileHeaderOpen(false)));
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&mobileMenuButton.getAttribute('aria-expanded')==='true'){setMobileHeaderOpen(false);mobileMenuButton.focus()}});
window.matchMedia('(min-width:701px)').addEventListener('change',event=>{if(event.matches)setMobileHeaderOpen(false)});
